{noformat}private getSelectedOrDefaultCategoryIndex(
        ctx: Context,
        categories: SearchCategory[],
        request: GetCategoryPriceInfoRequest,
        responseCode: number = ResponseCodes.AREA_NOT_SERVICED
    ): number {
        if (categories.length === 0) {
            logger.warning(ctx, "no categories available", {requestedId: request.category_id});
            throw BoltError.code(responseCode, "ca1da41f-458b-43ca-b9ba-215cb4f1750d");
        }
        let categoryIndex =
            request.category_id !== undefined ? categories.findIndex((c) => c.id === request.category_id) : 0;

        if (request.category_id && categoryIndex < 0) {
            const requestedSearchCategory = this.searchCategories.getSearchCategory(request.category_id);
            if (requestedSearchCategory) {
                categoryIndex = categories.findIndex((c) => c.group === requestedSearchCategory.group);
                logger.info(ctx, "requested category not found, trying substitute", {
                    user_id: request.user_id,
                    request_category_id: request.category_id,
                    request_category_group: requestedSearchCategory.group,
                    category_index: categoryIndex
                });
            }
        }

        if (categoryIndex < 0) {
            if (request.fallback_to_first_available) {
                return 0;
            }
            const meta = {requestedId: request.category_id, categories};
            logger.warning(ctx, "requested pricing for unavailable category", meta);
            throw BoltError.code(ResponseCodes.SELECTED_CATEGORY_UNAVAILABLE, "9cd6f5a7-6f7c-4ca3-9b28-5627de0c1435");
        }

        return categoryIndex;
    }{noformat}

